import json, struct

def varint(b, i):
    v = 0
    for k in range(9):
        c = b[i + k]
        if k == 8:
            return (v << 8) | c, i + 9
        v = (v << 7) | (c & 0x7F)
        if not c & 0x80:
            return v, i + k + 1

def value(t, b, i):
    sizes = {0: 0, 1: 1, 2: 2, 3: 3, 4: 4, 5: 6, 6: 8, 7: 8, 8: 0, 9: 0}
    if t in sizes:
        n = sizes[t]
        raw = b[i:i + n]
        if t == 7:
            return struct.unpack('>d', raw)[0], n
        if t in (8, 9):
            return t - 8, 0
        if t == 0:
            return None, 0
        return int.from_bytes(raw, 'big', signed=True), n
    n = (t - 12) // 2 if t % 2 == 0 else (t - 13) // 2
    raw = b[i:i + n]
    return (raw.decode('utf-8', 'replace') if t % 2 else raw), n

def parse_cell(b, off):
    _, i = varint(b, off)
    rowid, i = varint(b, i)
    hstart = i
    hlen, j = varint(b, i)
    types = []
    while j < hstart + hlen:
        t, j = varint(b, j)
        types.append(t)
    i = hstart + hlen
    cols = []
    for t in types:
        v, n = value(t, b, i)
        if i + n > len(b):
            raise ValueError('truncated')
        cols.append(v)
        i += n
    return rowid, cols

data = open('/app/trunc.db', 'rb').read()
PAGE = 4096
rows = {}
for p in range(0, len(data), PAGE):
    page = data[p:p + PAGE]
    h = 100 if p == 0 and page[:16] == b'SQLite format 3\x00' else 0
    if page[h] != 0x0D:
        continue
    ncell = struct.unpack('>H', page[h + 3:h + 5])[0]
    for c in range(ncell):
        ptr = struct.unpack('>H', page[h + 8 + 2 * c:h + 10 + 2 * c])[0]
        try:
            rowid, cols = parse_cell(page, ptr)
        except Exception:
            continue
        texts = [x for x in cols if isinstance(x, str)]
        nums = [x for x in cols if isinstance(x, (int, float)) and not isinstance(x, bool)]
        if texts:
            rows[rowid] = {'word': texts[0], 'value': nums[0] if nums else None}

out = [rows[k] for k in sorted(rows)]
json.dump(out, open('/app/recover.json', 'w'))
print(len(out), out)
EOF
./envrun 'cat > /app/recover.py' < recover.py && ./envrun 'python3 /app/recover.py && python3 -c "import json;print(len(json.load(open(\"/app/recover.json\"))))"'
